const THUMB_ACCENTS = ["#FF4800", "#1A1A1A", "#E23F00", "#3A3A38"];
function courseThumbHtml(course, index) {
  const icon = COURSE_ICON[course.slug] || CATEGORY_ICON[course.category] || "book-open";
  const accent = THUMB_ACCENTS[(index != null ? index : course.slug.length) % THUMB_ACCENTS.length];
  const photoUrl = `/assets/images/thumbs/${course.slug}.jpg`;
  return `<div class="course-card-thumb" style="--thumb-accent: ${accent};">
    <i class="ph-fill ph-${icon} course-cover-icon"></i>
    <img src="${photoUrl}" alt="${course.name}" loading="lazy" onload="this.classList.add('is-loaded')" onerror="this.remove()">
  </div>`;
}

